// ServerCertificate The certificate a server presented to a connection's test, and
// whether rvav trusts it (ADR-0030): the system's CAs and the CA
// bundle's (Integrations › Trusted certificates) vouch for it, or it is
// the connection's pinned certificate.
type ServerCertificate struct {
	// Address The host and port read.
	//
	// Examples: vc01.corp.example:443
	Address string `json:"address"`

	// AnchorIsLeaf The anchor is the server's own certificate (self-signed, or sent without its CA).
	AnchorIsLeaf bool `json:"anchor_is_leaf"`

	// AnchorPem The last certificate the server sent, in PEM; in the CA bundle, it makes the server trusted.
	AnchorPem string `json:"anchor_pem"`

	// AnchorSubject Examples: Corp Issuing CA 2
	AnchorSubject string `json:"anchor_subject"`

	// Checked False when the connection doesn't check certificates (insecure).
	Checked bool `json:"checked"`

	// Issuer Examples: Corp Issuing CA 2
	Issuer string `json:"issuer"`

	// Names The names and addresses it is for.
	Names     []string  `json:"names"`
	NotAfter  time.Time `json:"not_after"`
	NotBefore time.Time `json:"not_before"`

	// Pinnable The connection takes a pinned certificate (cert_sha256).
	Pinnable bool `json:"pinnable"`

	// Pinned It is the connection's pinned certificate.
	Pinned bool `json:"pinned"`

	// Problem Why the CAs don't vouch for it.
	Problem *string `json:"problem,omitempty"`

	// Sha256 Its SHA-256, as AB:CD:…; set as the connection's cert_sha256, the connection trusts it.
	Sha256 string `json:"sha256"`

	// Subject Examples: vc01.corp.example
	Subject string `json:"subject"`

	// Trusted The system's or the CA bundle's CAs vouch for it, for this host.
	Trusted bool `json:"trusted"`
}

